import {questions,stories,tracks,phrases,readingIntro,readingComments,extraPhrases,readingHighlights,expressionNotes} from './lesson6-data.js';
import {sections,createProfile,isComplete,answer,totals,mistakes,recommendation,rewards,stickers} from './lesson6-engine.js';
const root=document.querySelector('#app'),key='connect-lesson6-v3';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const preview=new URLSearchParams(location.search).has('preview');
let db={profiles:[]},profile=null,practice=false,retryId=null,buddy={step:0,a:null,b:null},audioError=false;
try{const data=preview?null:JSON.parse(localStorage.getItem(key)||'null');if(data&&Array.isArray(data.profiles))db=data;}catch{}
function save(){if(preview)return;try{localStorage.setItem(key,JSON.stringify(db));}catch{toast('저장 공간이 부족해 이번 변경을 저장하지 못했어요. 화면을 닫기 전에 결과를 내려받아 주세요.');}}
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.hidden=true,4500);}
function stopAudio(){document.querySelectorAll('audio').forEach(a=>a.pause());}
function playOnly(player){document.querySelectorAll('audio').forEach(a=>{if(a!==player)a.pause();});}
function on(id,event,fn){const el=document.getElementById(id);if(el)el.addEventListener(event,fn);}
function buttons(selector,fn){root.querySelectorAll(selector).forEach(b=>b.addEventListener('click',()=>fn(b)));}
function move(section){if(section==='collocation')collocationQuiz=false;stopAudio();practice=false;retryId=null;profile.section=section;save();render();window.scrollTo(0,0);}
let pendingSection=null,collocationQuiz=false;
function activityMenu(active){return `<nav class="activity-nav" aria-label="학습 활동">${sections.map((s,i)=>`<button data-section="${s.id}" class="${active===s.id?'active':''}" ${active===s.id?'aria-current="page"':''}><span class="tab-icon">${s.icon}</span><span>${s.title}<small>${s.ko}</small></span><span class="tab-number">0${i+1}</span></button>`).join('')}</nav>`;}
const readingChunks=readingHighlights;
function chunkMarkup(text,chunks){const ranges=[];for(const phrase of [...chunks].sort((a,b)=>b.length-a.length)){let from=0,index;while((index=text.toLowerCase().indexOf(phrase.toLowerCase(),from))>=0){const end=index+phrase.length;if(!ranges.some(r=>index<r.end&&end>r.start))ranges.push({start:index,end});from=end;}}ranges.sort((a,b)=>a.start-b.start);let last=0,out='';for(const r of ranges){out+=esc(text.slice(last,r.start))+'<button type="button" class="collocation-underline chunk-button '+(expressionNotes[text.slice(r.start,r.end).toLowerCase()]?.kind==='연어'||expressionNotes[text.slice(r.start,r.end).toLowerCase()]?.kind==='추가 연어'?'':'fixed-expression')+'" data-chunk="'+esc(text.slice(r.start,r.end).toLowerCase())+'" aria-haspopup="dialog">'+esc(text.slice(r.start,r.end))+'</button>';last=r.end;}return out+esc(text.slice(last));}

const chunkHelp=expressionNotes;
root.addEventListener('click',e=>{const button=e.target.closest('[data-chunk]');if(!button)return;const help=chunkHelp[button.dataset.chunk];if(!help)return;const dialog=document.createElement('dialog');dialog.className='chunk-dialog';dialog.innerHTML=`<button class="text-button chunk-close" aria-label="설명 닫기">닫기 ×</button><span class="eyebrow">${esc(help.kind)} · 뜻과 쓰임</span><h2 lang="en">${esc(button.textContent)}</h2><h3>${esc(help.title)}</h3><p>${esc(help.description)}</p><a href="${esc(help.sourceUrl)}" target="_blank" rel="noopener noreferrer">사전·용례 근거 보기 ↗</a><details><summary>COCA 빈도·결합 근거</summary><p class="help-text">${esc(help.corpusNote)} 사전 용례 확인과 통계 검증은 다릅니다.</p></details>`;document.body.append(dialog);dialog.querySelector('button').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{dialog.remove();button.focus();});dialog.showModal();});
function collocationStudy(main){main.innerHTML=`<div class="section-heading"><div><div class="eyebrow">COLLOCATION · STUDY FIRST</div><h1>번호로 정리하는 표현 노트</h1><p>사전·교육 용례를 검토한 학습 연어예요. COCA 확인 대기 중이며, 현재 번호와 문제 순서는 빈도 순위가 아닙니다.</p></div></div><p class="help-text">someone = 누군가 · one’s = 자신의 (my, your, his, her 등). 예문에는 실제 문맥의 인칭을 그대로 사용해요.</p><div class="phrase-study">${phrases.map((p,i)=>`<article class="phrase-note"><span class="phrase-number">${String(i+1).padStart(2,'0')}</span><div><h2 lang="en">${esc(p.phrase)}</h2><strong>${esc(p.meaning)}</strong><p class="help-text"><b>${esc(p.evidenceLabel)}</b></p><p class="help-text">${esc(p.review)}</p><a href="${esc(p.sourceUrl)}" target="_blank" rel="noopener noreferrer">사전·용례 보기 ↗</a><details><summary>COCA 빈도·결합 근거</summary><p class="help-text">${esc(p.corpusNote)}</p></details><p class="help-text">${esc(p.explanation)}</p><p lang="en">${esc(p.example)}</p></div></article>`).join('')}</div><details class="extra-material"><summary>추가 연어 3개와 고정·관용 표현 2개 · 평가 문항 추가 없음</summary>${extraPhrases.map(p=>`<article class="phrase-note"><div><span class="badge">${esc(p.kind)}</span><h2>${esc(p.phrase)}</h2><strong>${esc(p.meaning)}</strong><p lang="en">${esc(p.example)}</p><p class="help-text">${esc(p.where)} · 통계 유의성 별도 미검증</p><a href="${esc(p.sourceUrl)}" target="_blank" rel="noopener noreferrer">용례 보기 ↗</a></div></article>`).join('')}</details><div class="phrase-start"><button id="start-collocation" class="primary">연어 8문제 풀기 →</button><p>각 5점 · 총 40점 · 문제를 풀다가 정리로 돌아올 수 있어요.</p></div>`;on('start-collocation','click',()=>{collocationQuiz=true;render();window.scrollTo(0,0);});}

function welcome(){stopAudio();profile=null;document.body.classList.add('cover-mode');root.innerHTML=`<main class="friendly-cover calm-cover"><header class="cover-banner"><div><span class="cover-course">YBM 중학교 영어 · Lesson 6</span><h1>Click, Connect, and Communicate</h1></div><span class="cover-score">총 <b>100점</b></span></header><section class="cover-playground"><div class="cover-emojis" aria-hidden="true"><span>📱</span><span>💬</span><span>🌐</span></div><h2>디지털 세상에서<br>마음을 나누는 영어</h2><p class="cover-description">친구들의 이야기를 듣고 읽으며,<br>감정을 표현하고 서로 이해하는 방법을 배워요.</p><div class="cover-learning-info"><span>${questions.length}문항 · 내 속도로 차근차근</span></div><form id="entry-form" class="name-tag-card"><label for="student-name">이름 또는 별명</label><div class="friendly-entry"><input id="student-name" name="name" autocomplete="nickname" maxlength="24" placeholder="이름을 입력해 주세요" required><button class="friendly-start" type="submit">학습 시작 <span>→</span></button></div><p>학습 기록을 저장하고, 다음에 이어서 공부할 수 있어요.</p></form>${db.profiles.length?`<details class="cover-resume calm-resume"><summary>이전 학습 이어서 하기</summary><div>${db.profiles.map((p,i)=>`<button data-profile="${i}" class="resume-chip">${esc(p.name)} <span>이어서 하기 →</span></button>`).join('')}</div></details>`:''}</section></main>`;
buttons('[data-section]',b=>{pendingSection=b.dataset.section;document.getElementById('student-name').focus();toast('이름을 입력하면 선택한 활동으로 이동해요.');});
on('entry-form','submit',e=>{e.preventDefault();const name=document.getElementById('student-name').value.trim();if(!name)return toast('이름이나 별명을 입력해 주세요.');profile=db.profiles.find(p=>p.name===name);if(!profile){profile=createProfile(name);db.profiles.push(profile);}if(pendingSection){profile.section=pendingSection;pendingSection=null;}save();render();});buttons('[data-profile]',b=>{profile=db.profiles[Number(b.dataset.profile)];if(pendingSection){profile.section=pendingSection;pendingSection=null;save();}render();});}
function shell(){document.body.classList.remove("cover-mode");const t=totals(profile);root.innerHTML=`<header class="site-header"><button class="brand brand-button" id="brand-home"><span class="brand-symbol">c<span>↗</span></span>connect<span class="brand-mini">LESSON 06</span></button><div class="student-tools"><button id="switch-student" class="student-chip"><span class="student-dot">${esc(profile.name.slice(0,1))}</span><span class="student-name">${esc(profile.name)}</span> <span>⌄</span></button><div class="score-chip" aria-label="첫 풀이 점수 ${t.score}점, 100점 만점"><span>MY SCORE</span><strong>${t.score}<small> / 100</small></strong></div></div></header><div class="learning-wrap"><div class="lesson-line"><span>Click, Connect, and Communicate</span><span>B1 목표 · ${t.done} / ${questions.length}문항 완료</span></div>${activityMenu(profile.section)}<main id="lesson-main" tabindex="-1"></main><footer class="learning-footer"><span>한 번에 한 문제, 내 속도로 연결해요.</span><span>이 기기에 학생별 기록 저장 · 공용 기기에서 열람 가능</span></footer></div>`;
on('brand-home','click',welcome);on('switch-student','click',welcome);buttons('[data-section]',b=>move(b.dataset.section));}
const warmCards=[{emoji:'😊',word:'happy',situation:'“My post got 50 likes!”',hint:'좋은 반응을 받은 Suho는 어떤 기분일까요?'},{emoji:'😴',word:'sleepy',situation:'“I read a book until late last night.”',hint:'늦게까지 책을 읽은 Jade의 기분이에요.'},{emoji:'😨',word:'scared',situation:'“I saw a ghost in my dream!”',hint:'꿈에서 유령을 본 Alex의 기분이에요.'},{emoji:'😟',word:'upset',situation:'“My dog bit my smartphone.”',hint:'스마트폰이 망가진 Lucy는 속상해요.'}];
function warmup(main){const done=warmCards.filter((_,i)=>profile.warm[i]).length;const i=warmCards.findIndex((_,i)=>!profile.warm[i]);main.innerHTML=`<div class="section-heading"><div><div class="eyebrow">WARM-UP · NO SCORE</div><h1>오늘의 마음을 연결해요 <span>☺</span></h1><p>상황을 읽고 어울리는 감정을 눌러 보세요. 점수 없이 가볍게 시작해요.</p></div><span class="section-counter">${done} / 4</span></div><section class="warmup-card">${i<0?`<div class="warm-emoji">🙌</div><h2>감정 연결 완료!</h2><p>${esc(profile.name)}님, 이제 대화 속 마음을 직접 들어볼까요?</p><button class="primary" id="warm-next">Listening 시작 →</button>`:`<span class="badge">MESSAGE ${i+1}</span><div class="warm-message"><span>💬</span><h2>${warmCards[i].situation}</h2></div><p>How does this person feel?</p><div class="emotion-options">${[0,2,1,3].map(n=>`<button data-emotion="${n}" aria-label="${warmCards[n].word}"><span>${warmCards[n].emoji}</span><strong>${warmCards[n].word}</strong></button>`).join('')}</div><div id="warm-feedback" role="status" class="warm-feedback"></div>`}</section><div class="warm-bottom"><span>TRY → FEEL → CONNECT</span><button class="text-button" id="skip-warm">바로 듣기로 이동 →</button></div>`;
on('warm-next','click',()=>move('listening'));on('skip-warm','click',()=>move('listening'));buttons('[data-emotion]',b=>{const ok=Number(b.dataset.emotion)===i;const feedback=document.getElementById('warm-feedback');if(ok){profile.warm[i]=true;save();root.querySelectorAll('[data-emotion]').forEach(x=>x.disabled=true);b.classList.add('correct');feedback.innerHTML=`<strong>맞아요! ${esc(profile.name)}님, ${warmCards[i].word}와 연결했어요.</strong><button id="next-warm" class="primary">${done===3?'워밍업 완료':'다음 감정 →'}</button>`;on('next-warm','click',()=>render());}else{b.classList.add('wrong');feedback.textContent=warmCards[i].hint;}});}
function mission(q,r){
 const done=r&&!practice,name=q.area==='reading'?(q.ref||'루미'):'루미';
 const opening={listening:'친구가 왜 그렇게 말했을까? 함께 들어보자!',reading:'내 이야기를 읽고, 상황을 이해해 줄래?',collocation:'이 상황에 딱 맞는 표현을 함께 찾아보자!'};
 const reply=done?(r.correct?(r.attempts>1?'다시 생각해서 연결했네. 이제 내 표현이 됐어!':q.area==='reading'?'내 이야기를 이해해 줘서 고마워!':q.area==='listening'?'맞아! 말 속에 담긴 마음을 찾았네.':'좋아! 이 표현은 다음 대화에서도 써 보자.'):(r.skipped?'괜찮아. 준비되면 다시 만나자!':'괜찮아, 단서를 다시 연결해 보자.')):opening[q.area];
 return `<aside class="chat-mission" aria-label="채팅 미션"><div class="chat-friend"><span class="chat-face" aria-hidden="true">${done?(r.correct?'😊':'🤔'):'💬'}</span><div><strong>${esc(name)}</strong><small>학습 속 가상 친구 · CHAT MISSION</small></div><span class="chat-state">${done&&r.correct?'마음 연결 ✓':'연결 중'}</span></div><p class="chat-bubble">${esc(reply)}</p>${done&&!r.correct&&!r.skipped?`<p class="chat-clue">💡 ${esc(q.hint)}</p>`:''}${done&&r.correct&&!r.firstCorrect&&r.attempts>1?'<div class="recovery-stamp">🌱 실수 → 내 실력으로!</div>':''}</aside>`;
}
function stickerShelf(){const r=rewards(profile);return `<section class="sticker-shelf" aria-label="나의 스티커"><div class="row-between"><strong>나의 연결 스티커 ${r.earned.length} / 6</strong><span>${r.remaining?`다음 스티커까지 ${r.remaining}문항`:'스티커 컬렉션 완성!'}</span></div><p class="help-text">정답 여부와 관계없이 직접 답한 서로 다른 3문항마다 하나씩! 건너뛰기는 제외하며 점수는 그대로예요.</p><div class="sticker-grid">${stickers.map((s,i)=>`<span class="sticker ${i<r.earned.length?'earned':'waiting'}">${i<r.earned.length?s:'🔒 '+s.slice(3)}</span>`).join('')}</div>${r.recovered?`<p class="recovery-stamp">🌱 실수 → 내 실력으로! · ${r.recovered}문항 복습 성공</p>`:''}</section>`;}
function questionView(main){const area=profile.section,pool=questions.filter(q=>q.area===area);let index=Math.min(profile.position[area]||0,pool.length-1);const q=practice?questions.find(q=>q.id===retryId):pool[index];if(!q){practice=false;return move('review');}const result=profile.answers[q.id],locked=Boolean(result)&&!practice,draft=profile.drafts[q.id],track=tracks.find(t=>t.id===q.trackId),story=stories.find(s=>s.name===q.ref);const titles={listening:['LISTEN & CONNECT','듣고, 마음을 이해해요','대화의 이유와 의도를 찾아보세요.'],reading:['READ & CONNECT','What Should I Do?','세 친구의 고민 속에서 단서와 표현을 찾아보세요.'],collocation:['NOTICE & CONNECT','함께 쓰이는 표현을 찾아요','단어 하나보다, 상황에 맞는 표현을 한 덩어리로 기억해요.']};const [tag,title,sub]=titles[area];
main.innerHTML=`<div class="section-heading"><div><div class="eyebrow">${practice?'RETRY · 점수 추가 없음':tag}</div><h1>${title}</h1><p>${sub}</p></div><span class="section-counter">${totals(profile,area).score}<small> / ${totals(profile,area).max}점</small></span></div>${area==='collocation'?'<button id="back-phrases" class="text-button">← 번호별 연어 정리 다시 보기</button>':''}<div class="question-path"><div class="question-dots" aria-label="문항 선택">${pool.map((x,n)=>`<button data-q="${n}" class="${q.id===x.id?'current':''} ${profile.answers[x.id]?'done':''}" aria-label="${n+1}번 ${profile.answers[x.id]?'풀이 완료':'미응답'}" ${q.id===x.id?'aria-current="step"':''}>${profile.answers[x.id]?'✓':n+1}</button>`).join('')}</div><span>${q.category==='Matching'?'Matching · 알맞은 연결 고르기':q.category==='Expression'?'Expression · 문맥 속 표현':q.category==='Comprehension'?'Comprehension · 내용 이해':area==='listening'?'듣기 7문항 · 각 5점':'연어 8문항 · 각 5점'}</span></div><div class="exercise-layout ${area==='collocation'?'single-column':''}"><section class="source-panel">${story?`<div class="source-top"><span class="source-avatar">${story.icon}</span><div><span class="eyebrow">${story.name.toUpperCase()}'S STORY</span><h2>${esc(story.title)}</h2></div><span class="source-page">${esc(story.sourceLabel)}</span></div><div class="reading-audio-box"><button id="read-play" class="text-button">▶ 본문 듣기</button><audio id="reading-audio" controls preload="metadata" src="${story.audio}"></audio><div class="audio-tools"><label for="reading-speed">속도 <select id="reading-speed"><option value="0.8">0.8×</option><option value="1" selected>1×</option><option value="1.2">1.2×</option></select></label><button id="read-replay" class="text-button">↻ 처음부터</button><a class="audio-download" href="${story.audio}" download>음원 저장 ↓</a></div><p class="source-note" id="reading-status" role="status">교과서 본문·조언을 읽은 생성 음성</p></div><div class="reading-discovery"><p>먼저 듣고 읽은 뒤 표시 버튼을 눌러보세요. 실선은 연어, 점선은 고정·관용 표현이에요. 밑줄을 누르면 뜻과 근거를 볼 수 있어요.</p><button id="show-collocations" class="secondary" aria-pressed="false">연어·표현 표시하기</button></div><div class="story-body" id="reading-body" lang="en">${esc(story.text)}</div><div class="advice-bubble" id="reading-advice" ${readingComments[story.name].length?'':'hidden'}><span>💡 Friends' advice</span>${readingComments[story.name].map(line=>`<p lang="en">${esc(line)}</p>`).join('')}</div><details class="translation"><summary>한국어 도움말</summary><p>${esc(story.ko)}</p></details>`:track?`<div class="source-top"><span class="source-avatar">🎧</span><div><span class="eyebrow">LISTEN & SPEAK</span><h2>${esc(track.title)}</h2></div><span class="source-page">p.${track.page}</span></div><div class="audio-art" aria-hidden="true"><span class="earphone">🎧</span><div class="waveform">${[18,32,45,26,56,38,64,44,28,50,36,22,40,18].map(h=>`<i style="--bar:${h}px"></i>`).join('')}</div><p>Listen to the conversation</p></div><button id="play-main" class="play-main">▶ ${profile.heard[q.id]?'다시 듣기':'대화 듣기'}</button><audio id="lesson-audio" controls preload="metadata" src="${track.audio}"></audio><div class="audio-tools"><label for="audio-speed">재생 속도 <select id="audio-speed"><option value="0.8">0.8× 천천히</option><option value="1" selected>1× 보통</option><option value="1.2">1.2×</option></select></label><button id="replay-audio" class="text-button">↻ 처음부터</button></div><p id="audio-status" role="status" class="source-note">${profile.heard[q.id]?'들은 내용을 바탕으로 답해 보세요.':'먼저 대화를 재생한 뒤 답을 확인해요.'}</p><details id="script-details" ${profile.scripts[q.id]?'open':''}><summary>대본 확인 · 먼저 듣고 열어보세요</summary><div class="script-lines">${track.lines.map(([who,line])=>`<p><strong>${who==='SFX'?'효과':who}</strong><span lang="en">${esc(line)}</span></p>`).join('')}</div></details><p class="source-note">제공 스크립트로 만든 영어 합성 음성입니다.<br>교과서 원음이 아니며, 음악 효과는 생략했습니다.</p>`:`<span class="eyebrow">COLLOCATION LAB</span><div class="coll-art" aria-hidden="true"><span>🔗</span><div>words<br><b>belong together.</b></div></div><p>표현을 상황에 연결하면 더 오래 기억할 수 있어요.</p>`}</section><section class="question-panel" aria-label="문제"><div class="question-meta"><span class="badge">${practice?'다시 도전':`QUESTION ${index+1} / ${pool.length}`}</span><span>${q.points}점</span></div>${mission(q,locked?result:null)}<h2 class="question-title" lang="en">${esc(q.prompt)}</h2><fieldset class="response-options" ${locked?'disabled':''}><legend class="sr-only">정답 선택</legend>${q.type==='match'?`<p class="help-text">왼쪽 항목과 어울리는 설명을 각각 골라주세요.</p>${q.pairs.map(([left],n)=>`<label class="match-row"><strong>${esc(left)}</strong><select data-match="${n}"><option value="">설명을 선택하세요</option>${[2,0,1].map(j=>`<option value="${j}" ${String((locked?result.response:draft)?.[n])===String(j)?'selected':''}>${esc(q.pairs[j][1])}</option>`).join('')}</select></label>`).join('')}`:q.options.map((o,n)=>`<label class="option ${locked&&n===q.answer?'correct':''} ${locked&&!result.correct&&String(result.response)===String(n)?'wrong':''}"><input type="radio" name="response" value="${n}" ${String(locked?result.response:draft)===String(n)?'checked':''}><span class="option-letter">${String.fromCharCode(65+n)}</span><span>${esc(o)}</span>${locked&&n===q.answer?'<small>정답</small>':''}</label>`).join('')}</fieldset><div class="question-actions"><button id="hint" class="hint-button" aria-expanded="${Boolean(profile.hints[q.id])}">💡 힌트</button><button id="check" class="primary" ${locked?'disabled':''}>${locked?'확인 완료':'정답 확인'}</button></div><p id="hint-text" class="hint-text" ${profile.hints[q.id]?'':'hidden'}>${esc(q.hint)} <small>힌트 사용은 감점하지 않아요.</small></p><div id="question-feedback" aria-live="polite">${locked?feedback(q,result):''}</div><div class="question-bottom">${locked?`<button id="next" class="primary next-button">${retryId?'복습 결과 보기':index===pool.length-1?'다음 활동으로 →':'다음 문제 →'}</button>`:`<button id="skip" class="text-button">나중에 풀기</button><span class="help-text">건너뛰면 첫 풀이 점수는 0점입니다.</span>`}</div>${practice?'<button id="exit-practice" class="text-button">복습 목록으로</button>':''}</section></div>${false?`<details class="extra-material"><summary>What Should I Do? · 도입부 읽고 듣기</summary><p class="help-text">먼저 도입부를 듣고 읽은 뒤, 연어 표시를 눌러보세요.</p><button id="intro-chunks" class="secondary" aria-pressed="false">도입부 연어·표현 표시하기</button><p class="intro-text" id="intro-reading-body" lang="en">${esc(readingIntro)}</p><audio id="intro-audio" controls preload="none" src="audio/reading-intro.wav"></audio><a class="audio-download" href="audio/reading-intro.wav" download>도입부 음원 저장 ↓</a></details>`:''}${area==='listening'?`<details class="extra-material"><summary>더 듣고 싶다면? · 제공 스크립트 전체 12개</summary><label for="extra-track">대화 선택</label><select id="extra-track">${tracks.map(t=>`<option value="${t.id}">${esc(t.part)} · ${esc(t.title)}</option>`).join('')}</select><audio id="extra-audio" controls preload="none" src="${tracks[0].audio}"></audio><p class="help-text">추가 듣기는 점수에 포함되지 않습니다.</p></details>`:''}`;
on('back-phrases','click',()=>{collocationQuiz=false;practice=false;retryId=null;render();});buttons('[data-q]',b=>{stopAudio();practice=false;retryId=null;profile.position[area]=Number(b.dataset.q);save();render();});
root.querySelectorAll('input[name=response]').forEach(el=>el.addEventListener('change',()=>{profile.drafts[q.id]=el.value;save();}));root.querySelectorAll('[data-match]').forEach(el=>el.addEventListener('change',()=>{profile.drafts[q.id]=[...root.querySelectorAll('[data-match]')].map(e=>e.value);save();}));
on('hint','click',()=>{profile.hints[q.id]=true;save();document.getElementById('hint-text').hidden=false;document.getElementById('hint').setAttribute('aria-expanded','true');});
const finish=skip=>{if(!skip&&!isComplete(q,profile.drafts[q.id])){document.getElementById('question-feedback').innerHTML='<p class="missing-alert" role="alert">아직 답하지 않은 항목이 있어요. 답을 모두 고른 뒤 확인해 주세요.</p>';return;}if(!skip&&track&&!profile.heard[q.id]&&!profile.scripts[q.id])return toast('먼저 대화를 재생해 주세요. 음원에 문제가 있으면 대본으로 연습할 수 있어요.');const before=rewards(profile).earned.length;const out=answer(profile,q,profile.drafts[q.id]??null,{skip,practice});if(out.error)return;practice=false;save();render();const earned=rewards(profile).earned;if(earned.length>before){const reward=document.createElement('div');reward.className='sticker-unlock';reward.setAttribute('role','status');reward.textContent='🎉 새 스티커! '+earned[earned.length-1];document.getElementById('question-feedback').prepend(reward);}const box=document.getElementById('question-feedback');box?.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'nearest'});document.getElementById('next')?.focus({preventScroll:true});};
on('retry-now','click',()=>{delete profile.drafts[q.id];practice=true;collocationQuiz=true;retryId=q.id;save();render();});on('check','click',()=>finish(false));on('skip','click',()=>finish(true));on('next','click',()=>{if(retryId){retryId=null;return move('review');}if(index<pool.length-1){profile.position[area]=index+1;save();render();window.scrollTo(0,0);}else move(area==='listening'?'reading':area==='reading'?'collocation':'review');});on('exit-practice','click',()=>move('review'));
if(story){let showChunks=false,introChunks=false;on('show-collocations','click',()=>{showChunks=!showChunks;document.getElementById('reading-body').innerHTML=showChunks?chunkMarkup(story.text,readingChunks[story.name]):esc(story.text);document.getElementById('reading-advice').innerHTML=`<span>💡 Friends' advice</span>${readingComments[story.name].map(line=>`<p lang="en">${showChunks?chunkMarkup(line,readingChunks[story.name]):esc(line)}</p>`).join('')}`;const button=document.getElementById('show-collocations');button.textContent=showChunks?'표시 숨기기':'연어·표현 표시하기';button.setAttribute('aria-pressed',String(showChunks));});on('intro-chunks','click',()=>{introChunks=!introChunks;document.getElementById('intro-reading-body').innerHTML=introChunks?chunkMarkup(readingIntro,readingChunks.intro):esc(readingIntro);const button=document.getElementById('intro-chunks');button.textContent=introChunks?'도입부 표시 숨기기':'도입부 연어·표현 표시하기';button.setAttribute('aria-pressed',String(introChunks));});const reader=document.getElementById('reading-audio');on('read-play','click',async()=>{if(!reader.paused)return reader.pause();try{await reader.play();}catch{toast('오디오 재생 버튼을 눌러 주세요.');}});on('reading-audio','play',()=>playOnly(reader));on('reading-speed','change',e=>reader.playbackRate=Number(e.target.value));on('read-replay','click',async()=>{reader.currentTime=0;try{await reader.play();}catch{toast('재생 버튼을 눌러 주세요.');}});on('reading-audio','error',()=>{document.getElementById('reading-status').textContent='음원을 불러오지 못했어요. START.cmd로 앱을 실행해 주세요.';});const introPlayer=document.getElementById('intro-audio');if(introPlayer)introPlayer.onplay=()=>playOnly(introPlayer);}
if(track){const player=document.getElementById('lesson-audio');audioError=false;on('lesson-audio','play',()=>{playOnly(player);profile.heard[q.id]=true;save();document.getElementById('audio-status').textContent='재생 중 · 필요한 만큼 반복해서 들어보세요.';document.querySelector('.audio-art')?.classList.add('playing');});on('lesson-audio','pause',()=>document.querySelector('.audio-art')?.classList.remove('playing'));on('lesson-audio','ended',()=>{document.getElementById('audio-status').textContent='잘 들었어요. 들은 내용을 떠올려 답을 골라보세요.';});on('lesson-audio','error',()=>{audioError=true;document.getElementById('audio-status').textContent='음원을 불러오지 못했어요. 앱을 START.cmd로 실행했는지 확인하거나 대본으로 연습하세요.';});const play=async()=>{try{await player.play();}catch{toast('재생되지 않았어요. 오디오 재생 버튼을 다시 눌러 주세요.');}};on('play-main','click',()=>{if(player.paused)play();else player.pause();});on('replay-audio','click',()=>{player.currentTime=0;play();});on('audio-speed','change',e=>player.playbackRate=Number(e.target.value));on('script-details','toggle',e=>{if(e.target.open){profile.scripts[q.id]=true;save();}});on('extra-track','change',e=>{const extra=document.getElementById('extra-audio');extra.pause();extra.src=tracks.find(t=>t.id===e.target.value).audio;extra.load();});on('extra-audio','play',()=>playOnly(document.getElementById('extra-audio')));}
}
function feedback(q,r){const gained=r.attempts===1&&r.firstCorrect?q.points:0;return `<div class="feedback ${r.correct?'success':'try-again'}"><div class="feedback-title"><span>${r.correct?'✦':'↻'}</span><strong>${esc(profile.name)}님, ${r.correct?'잘 연결했어요!':r.skipped?'복습 목록에 남겨두었어요.':'근거를 함께 살펴봐요.'}</strong>${gained?`<b class="points-pop">+${gained}</b>`:''}</div><p>${esc(q.why)}</p><div class="answer-key"><strong>정답</strong>${q.type==='match'?q.pairs.map(([l,r])=>`<p>${esc(l)} → ${esc(r)}</p>`).join(''):`<p>${esc(q.options[q.answer])}</p>`}</div><small>${r.attempts>1?'복습에서는 점수가 추가되지 않습니다. 첫 풀이 점수는 유지돼요.':r.skipped?'건너뛴 문항은 0점으로 기록되고 다시 풀 수 있어요.':r.correct?'이 표현을 다음 상황에서도 떠올려 보세요.':'틀린 문항은 Self-review에서 다시 풀 수 있어요.'}${r.script?' · 대본을 확인한 연습입니다.':''}</small>${!r.correct?'<button id="retry-now" class="secondary retry-chat">↻ 다시 연결하기 · 점수 추가 없음</button>':''}</div>`;}
function selfReview(main){const t=totals(profile),wrong=mistakes(profile),rec=recommendation(profile),skipped=questions.map(q=>profile.answers[q.id]).filter(Boolean).filter(a=>a.firstSkipped).length,scripts=questions.map(q=>profile.answers[q.id]).filter(Boolean).filter(a=>a.script).length;main.innerHTML=`<div class="section-heading"><div><div class="eyebrow">SELF-REVIEW · MY LEARNING</div><h1>${esc(profile.name)}님의 오늘의 연결 <span>✦</span></h1><p>${t.done===questions.length?'끝까지 도전했어요. 배운 표현을 내 것으로 만들어 볼까요?':'아직 풀지 않은 문제를 확인하고, 내 속도로 이어가세요.'}</p></div><button class="text-button" id="export-results">결과 내려받기 ↓</button></div><div class="review-layout"><section class="result-card"><span class="badge">${t.done===questions.length?'FINAL SCORE':'진행 중 · 현재 점수'}</span><div class="big-score">${t.score}<span>/ 100</span></div><p>${t.done} / ${questions.length}문항 완료 · 미응답 ${questions.length-t.done} · 건너뜀 ${skipped}</p><div class="area-results">${['listening','reading','collocation'].map(id=>{const a=totals(profile,id);return `<div><div><strong>${sections.find(s=>s.id===id).title}</strong><span>${a.score} / ${a.max}</span></div><div class="meter"><i style="width:${a.score/a.max*100}%"></i></div></div>`}).join('')}</div><p class="help-text">첫 풀이 점수입니다. 재시도해도 100점을 초과하지 않아요.${scripts?` 대본을 확인한 풀이 ${scripts}문항이 포함됩니다.`:''}</p><div class="recommend"><strong>다음 한 걸음</strong><p>${rec.message}</p><button id="continue-learning" class="primary">${t.done<questions.length?'이어서 학습하기 →':'추천 영역 살펴보기 →'}</button></div></section><section class="reflection-card"><h2>나는 얼마나 할 수 있나요?</h2><p class="help-text">점수에 반영되지 않는 자기평가예요.</p>${[['listen','대화를 듣고 상대방의 감정을 이해할 수 있어요.'],['read','온라인 상황의 문제와 이유를 찾을 수 있어요.'],['phrase','상황에 맞는 표현을 연결할 수 있어요.']].map(([id,text])=>`<div class="reflection-item"><p>${text}</p><div role="group" aria-label="${text}">${[['again','🤔','더 연습'],['okay','🙂','할 수 있어요'],['confident','😎','자신 있어요']].map(([v,emoji,label])=>`<button data-reflection="${id}" data-value="${v}" aria-pressed="${profile.reflection[id]===v}"><span>${emoji}</span>${label}</button>`).join('')}</div></div>`).join('')}<div id="self-status" role="status" class="help-text">선택한 내용은 자동으로 저장돼요.</div></section></div>${stickerShelf()}<section class="review-list"><div class="row-between"><h2>다시 연결할 문항 <span>${wrong.length}</span></h2><span class="help-text">정답으로 고치면 목록에서 빠져요.</span></div>${wrong.length?wrong.map(q=>`<button class="review-item" data-retry="${q.id}"><span class="badge">${sections.find(s=>s.id===q.area).title}</span><span>${esc(q.prompt)}</span><strong>다시 풀기 →</strong></button>`).join(''):`<p class="empty-message">${t.done?'현재 남은 오답이 없어요.':'문제를 풀면 필요한 복습이 여기에 모여요.'}</p>`}</section><details class="buddy-section"><summary>친구와 한 번 더 · 같은 기기에서 대화 선택하기</summary><div id="buddy-content"></div></details>`;
on('continue-learning','click',()=>{const pool=questions.filter(q=>q.area===rec.area);const n=pool.findIndex(q=>!profile.answers[q.id]);profile.position[rec.area]=Math.max(0,n);move(rec.area);});buttons('[data-reflection]',b=>{profile.reflection[b.dataset.reflection]=b.dataset.value;save();root.querySelectorAll(`[data-reflection="${b.dataset.reflection}"]`).forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.getElementById('self-status').textContent='자기평가를 저장했어요.';});buttons('[data-retry]',b=>{const q=questions.find(q=>q.id===b.dataset.retry);profile.section=q.area;profile.position[q.area]=questions.filter(x=>x.area===q.area).indexOf(q);delete profile.drafts[q.id];practice=true;collocationQuiz=true;retryId=q.id;save();render();});on('export-results','click',()=>{const data={name:profile.name,score:t.score,max:100,completed:t.done,answers:profile.answers,selfReview:profile.reflection,generatedAt:new Date().toISOString()};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='lesson6-learning-result.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});renderBuddy();}
function renderBuddy(){const el=document.getElementById('buddy-content');if(!el)return;const choices=["I'm sorry to hear that. Can I help?","I'm happy to hear that!","Please send me more messages.","Can you show me your new phone?"];el.innerHTML=buddy.step<2?`<p class="help-text">친구 A가 고른 뒤 기기를 친구 B에게 넘겨주세요. 상대의 선택은 둘 다 고른 뒤 공개됩니다. 점수 없는 말하기 활동입니다.</p><span class="badge">친구 ${buddy.step===0?'A':'B'}의 차례</span><h3>“Someone left rude comments on my post.”</h3><p>어떤 말로 반응할까요?</p><div class="buddy-choices">${choices.map((c,i)=>`<button data-buddy="${i}" class="option">${esc(c)}</button>`).join('')}</div>`:`<h3>서로의 선택을 비교해 보세요</h3><p>A: ${esc(choices[buddy.a])}</p><p>B: ${esc(choices[buddy.b])}</p><div class="hint-text">속상한 소식에는 “I'm sorry to hear that.”으로 공감할 수 있어요. 왜 그 표현을 골랐는지 서로 말해 보세요.</div><button id="buddy-again" class="secondary">다시 해보기</button>`;el.querySelectorAll('[data-buddy]').forEach(b=>b.onclick=()=>{buddy[buddy.step===0?'a':'b']=Number(b.dataset.buddy);buddy.step++;renderBuddy();});on('buddy-again','click',()=>{buddy={step:0,a:null,b:null};renderBuddy();});}
function render(){stopAudio();if(!profile)return welcome();if(!sections.some(s=>s.id===profile.section))profile.section='warmup';shell();const main=document.getElementById('lesson-main');if(profile.section==='warmup')warmup(main);else if(profile.section==='review')selfReview(main);else if(profile.section==='collocation'&&!practice&&!collocationQuiz)collocationStudy(main);else questionView(main);}
welcome();

